// Generated by sdk-typescript as a real loopback consumer of the generated facade.
import { create, fromJsonString, toJsonString } from "@bufbuild/protobuf";
import { expect, test } from "bun:test";
import { createObjectsClient, OBJECTS_METHODS, type RustOwnedInvoker } from "./objects-metadata";
import { CreateBucketRequestSchema, BucketSchema } from "../../../../typescript/packages/objects/generated/proto/objects/v2/objects_pb.js";

test("generated objects facade preserves Rust-owned route, JSON encoding, and private auth", async () => {
  let seenBody: unknown;
  const server = Bun.serve({
    port: 0,
    fetch: async (request) => {
      expect(request.method).toBe("POST");
      expect(new URL(request.url).pathname).toBe("/v2/objects/buckets/create");
      expect(request.headers.get("authorization")).toBe("Bearer loopback-token");
      seenBody = await request.json();
      return Response.json({});
    },
  });
  try {
    const endpoint = `http://127.0.0.1:${server.port}/`;
    const invoker: RustOwnedInvoker = {
      async invoke<TRequest, TResponse>(method: import("./objects-metadata").RustOwnedMethodMetadata, request: TRequest): Promise<TResponse> {
        const response = await fetch(new URL(method.path, endpoint), {
          method: method.httpMethod,
          headers: { authorization: "Bearer loopback-token", "content-type": "application/json" },
          body: toJsonString(CreateBucketRequestSchema, request as never),
        });
        return fromJsonString(BucketSchema, await response.text()) as TResponse;
      },
    };
    const client = createObjectsClient(invoker);
    const response = await client.createBucket(create(CreateBucketRequestSchema));
    expect(response).toEqual(create(BucketSchema));
    expect(seenBody).toBeDefined();
    expect(OBJECTS_METHODS.createBucket.path).toBe("v2/objects/buckets/create");
  } finally {
    server.stop(true);
  }
});
